create or replace function public.srk_admin_set_fixed_price_worker_allocations(
  p_booking_id uuid,
  p_allocations jsonb,
  p_reason text
)
returns integer
language plpgsql
security definer
set search_path to 'pg_catalog','public','auth'
as $function$
