create or replace function public.srk_admin_version_service_pricing_rule(
 p_pricing_rule_id uuid,
 p_pricing_unit text,
 p_technician_rate numeric,
 p_helper_rate numeric,
 p_base_hp numeric,
 p_base_hp_price numeric,
 p_hp_step_amount numeric,
 p_timer_enabled boolean,
 p_materials_charged_separately boolean,
 p_winding_charged_separately boolean,
 p_pricing_note text,
 p_hp_tiers jsonb,
 p_change_reason text
)
returns uuid
language plpgsql
security definer
set search_path = pg_catalog, public, auth
as $function$
declare
 v_old public.srk_service_pricing_rules%rowtype;
 v_new_id uuid;
 v_now timestamptz := clock_timestamp();
 v_tier_count integer := 0;
 v_bad_count integer := 0;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 if not public.srk_has_admin_permission('catalog.manage') then
  raise exception 'Permission denied: catalog.manage required';
 end if;
 if p_pricing_rule_id is null then raise exception 'Pricing rule ID is required'; end if;
 if p_pricing_unit not in ('hour','per_item','motor_hp') then raise exception 'Invalid pricing unit'; end if;
 if p_timer_enabled is null or p_materials_charged_separately is null or p_winding_charged_separately is null then
  raise exception 'Pricing flags are required';
 end if;
 if p_change_reason is null or length(btrim(p_change_reason)) < 10 then
  raise exception 'Change reason must contain at least 10 non-space characters';
 end if;
 if p_hp_tiers is null or jsonb_typeof(p_hp_tiers) <> 'array' then
  raise exception 'HP tiers must be supplied as a JSON array (use [] when not applicable)';
 end if;
 if p_pricing_unit='hour' then
  if p_technician_rate is null or p_technician_rate<=0 or p_timer_enabled is not true
     or p_base_hp is not null or p_base_hp_price is not null or p_hp_step_amount is not null
     or jsonb_array_length(p_hp_tiers)<>0 then
   raise exception 'Hourly pricing requires positive technician rate, timer enabled, and no HP fields/tiers';
  end if;
 elsif p_pricing_unit='per_item' then
  if p_technician_rate is null or p_technician_rate<=0 or p_timer_enabled is not false
     or p_base_hp is not null or p_base_hp_price is not null or p_hp_step_amount is not null
     or jsonb_array_length(p_hp_tiers)<>0 then
   raise exception 'Per-item pricing requires positive item rate, timer disabled, and no HP fields/tiers';
  end if;
 else
  if p_timer_enabled is not false or p_base_hp is null or p_base_hp<0.5
     or p_base_hp_price is null or p_base_hp_price<=0 or p_hp_step_amount is null or p_hp_step_amount<=0
     or p_technician_rate is not null or p_helper_rate is not null
     or jsonb_array_length(p_hp_tiers)=0 then
   raise exception 'Motor HP pricing requires timer disabled, positive HP base values and HP tiers';
  end if;
  if exists (
   select 1 from jsonb_to_recordset(p_hp_tiers) as x(motor_hp numeric, fixed_price numeric)
   where motor_hp is null or motor_hp<0.5 or fixed_price is null or fixed_price<=0
  ) then raise exception 'Every HP tier requires motor_hp >= 0.5 and positive fixed_price'; end if;
  select count(*) into v_tier_count from jsonb_to_recordset(p_hp_tiers) as x(motor_hp numeric,fixed_price numeric);
  select count(*) into v_bad_count from (
   select x.motor_hp from jsonb_to_recordset(p_hp_tiers) as x(motor_hp numeric,fixed_price numeric)
   group by x.motor_hp having count(*)>1
  ) d;
  if v_tier_count=0 or v_bad_count>0 then raise exception 'HP tiers must be non-empty and have unique HP values'; end if;
 end if;

 perform pg_advisory_xact_lock(hashtextextended(p_pricing_rule_id::text, 0));
 select * into v_old from public.srk_service_pricing_rules
 where id=p_pricing_rule_id for update;
 if not found then raise exception 'Pricing rule not found'; end if;
 if v_old.effective_to is not null then raise exception 'Only the current pricing rule version can be changed'; end if;
 if v_now<=v_old.effective_from then raise exception 'Pricing rule effective time conflict'; end if;

 update public.srk_service_pricing_rules set effective_to=v_now
 where id=v_old.id and effective_to is null;

 insert into public.srk_service_pricing_rules(
  category_id,service_type_id,pricing_unit,technician_rate,helper_rate,
  base_hp,base_hp_price,hp_step_amount,timer_enabled,
  materials_charged_separately,winding_charged_separately,pricing_note,
  effective_from,effective_to,created_by,change_reason
 ) values (
  v_old.category_id,v_old.service_type_id,p_pricing_unit,p_technician_rate,p_helper_rate,
  p_base_hp,p_base_hp_price,p_hp_step_amount,p_timer_enabled,
  p_materials_charged_separately,p_winding_charged_separately,
  nullif(btrim(p_pricing_note),''),v_now,nullif(null,'')::timestamptz,auth.uid(),btrim(p_change_reason)
 ) returning id into v_new_id;

 if p_pricing_unit='motor_hp' then
  insert into public.srk_service_pricing_hp_tiers(pricing_rule_id,motor_hp,fixed_price,created_by)
  select v_new_id,x.motor_hp,x.fixed_price,auth.uid()
  from jsonb_to_recordset(p_hp_tiers) as x(motor_hp numeric,fixed_price numeric);
 end if;
 return v_new_id;
end
$function$;

revoke all on function public.srk_admin_version_service_pricing_rule(uuid,text,numeric,numeric,numeric,numeric,numeric,boolean,boolean,boolean,text,jsonb,text) from public, anon;
grant execute on function public.srk_admin_version_service_pricing_rule(uuid,text,numeric,numeric,numeric,numeric,numeric,boolean,boolean,boolean,text,jsonb,text) to authenticated;

comment on function public.srk_admin_version_service_pricing_rule(uuid,text,numeric,numeric,numeric,numeric,numeric,boolean,boolean,boolean,text,jsonb,text)
is 'Admin-only immutable pricing versioning. Closes the prior rule and inserts a new version; old booking pricing_rule_id snapshots and old HP tiers remain unchanged.';

create or replace function public.srk_admin_update_service_rate(
 p_rate_id uuid,
 p_technician_hourly_rate numeric,
 p_helper_hourly_rate numeric,
 p_change_reason text
)
returns jsonb
language plpgsql
security definer
set search_path to 'pg_catalog','public','auth'
as $function$
declare
 v_old public.srk_service_rates%rowtype;
 v_new_id uuid;
 v_changed_at timestamptz := clock_timestamp();
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 if not public.srk_has_admin_permission('catalog.manage') then
  raise exception 'Catalog management permission required';
 end if;
 if p_rate_id is null then raise exception 'Rate ID is required'; end if;
 if p_technician_hourly_rate is null or p_technician_hourly_rate <= 0 then
  raise exception 'Technician hourly rate must be positive';
 end if;
 if p_helper_hourly_rate is not null and p_helper_hourly_rate <= 0 then
  raise exception 'Helper hourly rate must be positive when supplied';
 end if;
 if length(btrim(coalesce(p_change_reason,''))) < 10 then
  raise exception 'Rate change reason must be at least 10 characters';
 end if;

 select * into v_old from public.srk_service_rates
 where id=p_rate_id and effective_to is null and rate_status='approved'
 for update;
 if not found then
  raise exception 'Current approved legacy rate not found; drafts and retired rates cannot be changed here';
 end if;

 if exists (
  select 1 from public.srk_service_pricing_rules r
  where r.category_id=v_old.category_id
    and r.service_type_id=v_old.service_type_id
    and r.effective_from<=v_changed_at
    and (r.effective_to is null or r.effective_to>v_changed_at)
 ) then
  raise exception 'This service uses the versioned pricing rules. Update it through srk_admin_version_service_pricing_rule instead of the legacy hourly-rate manager';
 end if;

 update public.srk_service_rates
 set effective_to=v_changed_at,
     change_reason=concat_ws('; ',nullif(change_reason,''),'Superseded by admin rate adjustment')
 where id=v_old.id;

 insert into public.srk_service_rates(
  category_id,service_type_id,skill_level_id,technician_hourly_rate,
  helper_hourly_rate,rate_status,effective_from,created_by,change_reason
 ) values (
  v_old.category_id,v_old.service_type_id,v_old.skill_level_id,
  p_technician_hourly_rate,p_helper_hourly_rate,'approved',v_changed_at,
  auth.uid(),btrim(p_change_reason)
 ) returning id into v_new_id;

 return jsonb_build_object(
  'success',true,'previous_rate_id',v_old.id,'new_rate_id',v_new_id,
  'technician_hourly_rate',p_technician_hourly_rate,
  'helper_hourly_rate',p_helper_hourly_rate,'effective_from',v_changed_at
 );
end
$function$;
revoke all on function public.srk_admin_update_service_rate(uuid,numeric,numeric,text) from public,anon;
grant execute on function public.srk_admin_update_service_rate(uuid,numeric,numeric,text) to authenticated;
comment on function public.srk_admin_update_service_rate(uuid,numeric,numeric,text)
is 'Legacy hourly-rate versioning only for services without a current srk_service_pricing_rules row; prevents divergence from versioned pricing rules.';

create or replace function public.srk_worker_respond_assignment(
 p_assignment_id uuid,
 p_accept boolean
)
returns public.srk_booking_workers
language plpgsql
security definer
set search_path to 'pg_catalog','public','auth'
as $function$
declare
 v_assignment public.srk_booking_workers%rowtype;
 v_worker public.srk_worker_profiles%rowtype;
 v_booking public.service_bookings%rowtype;
 v_accepted_count integer;
 v_requested_count integer;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;

 select bw.* into v_assignment
 from public.srk_booking_workers bw
 join public.srk_worker_profiles wp on wp.id=bw.worker_id
 where bw.id=p_assignment_id and wp.user_id=auth.uid()
 for update of bw;

 if not found or v_assignment.assignment_status<>'offered' then
  raise exception 'Offer not found or no longer pending';
 end if;

 -- Serialize all acceptances for this Booking so concurrent responses cannot overfill a role.
 select * into v_booking
 from public.service_bookings
 where id=v_assignment.booking_id
 for update;

 if not found or v_booking.status='cancelled' then
  raise exception 'Booking is no longer available';
 end if;

 select * into v_worker
 from public.srk_worker_profiles
 where id=v_assignment.worker_id;

 if p_accept then
  if v_worker.verification_status<>'approved' or not v_worker.is_active then
   raise exception 'Worker is not currently approved and active';
  end if;

  v_requested_count:=case when v_assignment.worker_role='technician'
   then v_booking.requested_technician_count
   else v_booking.requested_helper_count end;

  select count(*) into v_accepted_count
  from public.srk_booking_workers
  where booking_id=v_assignment.booking_id
   and worker_role=v_assignment.worker_role
   and assignment_status in ('accepted','assigned','working','paused','completed');

  if v_accepted_count>=v_requested_count then
   raise exception 'Requested number of this worker role has already been filled';
  end if;
 end if;

 update public.srk_booking_workers
 set assignment_status=case when p_accept then 'accepted' else 'rejected' end,
  accepted_at=case when p_accept then clock_timestamp() else null end,
  rejected_at=case when p_accept then null else clock_timestamp() end,
  offer_expires_at=null,
  updated_at=clock_timestamp()
 where id=p_assignment_id
 returning * into v_assignment;

 -- First accepted Technician confirms immediately; later acceptances attach independently.
 if p_accept and v_assignment.worker_role='technician' then
  update public.service_bookings
  set status='confirmed'
  where id=v_assignment.booking_id and status='new';
 end if;

 -- Keep matching alive after confirmation until every requested Technician and Helper seat is filled.
 update public.srk_booking_matching_queue
 set queue_status='pending',next_attempt_at=clock_timestamp(),updated_at=clock_timestamp()
 where booking_id=v_assignment.booking_id
  and queue_status not in ('fulfilled','cancelled');

 return v_assignment;
end
$function$;

revoke all on function public.srk_worker_respond_assignment(uuid,boolean) from public,anon;
grant execute on function public.srk_worker_respond_assignment(uuid,boolean) to authenticated;
comment on function public.srk_worker_respond_assignment(uuid,boolean)
is 'Worker accepts/rejects own offer. First Technician acceptance confirms Booking immediately; subsequent role seats are filled independently. Booking row lock prevents concurrent over-acceptance.';

create or replace function public.srk_find_eligible_workers(p_booking_id uuid, p_worker_type text)
returns table(worker_id uuid, worker_code text, worker_type text, distance_km numeric)
language plpgsql
security definer
set search_path to 'pg_catalog','public'
as $function$
declare v_booking public.service_bookings%rowtype;
begin
  if p_worker_type not in ('technician','helper') then raise exception 'Invalid worker type'; end if;
  select * into v_booking from public.service_bookings where id=p_booking_id;
  if not found then raise exception 'Booking not found'; end if;
  if v_booking.booking_latitude is null or v_booking.booking_longitude is null then raise exception 'Booking GPS required'; end if;
  return query
  select w.id,w.worker_code,w.worker_type,
    round((6371*acos(least(1,greatest(-1,
      cos(radians(v_booking.booking_latitude))*cos(radians(w.location_lat))*cos(radians(w.location_lng)-radians(v_booking.booking_longitude))+
      sin(radians(v_booking.booking_latitude))*sin(radians(w.location_lat))
    ))))::numeric,2)
  from public.srk_worker_profiles w
  where w.worker_type=p_worker_type and w.category_id=v_booking.category_id
    and w.verification_status='approved' and w.is_active and w.is_online
    and w.location_lat is not null and w.location_lng is not null
    and exists(select 1 from public.srk_worker_skills ws where ws.worker_id=w.id and ws.skill_id=v_booking.selected_skill_id and ws.verification_status='approved')
    and (6371*acos(least(1,greatest(-1,
      cos(radians(v_booking.booking_latitude))*cos(radians(w.location_lat))*cos(radians(w.location_lng)-radians(v_booking.booking_longitude))+
      sin(radians(v_booking.booking_latitude))*sin(radians(w.location_lat))
    ))))<=least(30,w.service_radius_km)
    and not exists(
      select 1 from public.srk_worker_work_sessions s
      where s.worker_id=w.id and s.session_status in ('running','paused')
    )
    and not exists(
      select 1 from public.srk_booking_workers bw
      where bw.worker_id=w.id and bw.assignment_status in ('working','paused')
    )
    and not exists(select 1 from public.srk_worker_schedule_blocks sb where sb.worker_id=w.id
      and sb.block_status in ('reserved','confirmed','in_progress')
      and sb.starts_at<=clock_timestamp()+make_interval(hours=>coalesce(v_booking.requested_duration_hours,1))
      and sb.ends_at>clock_timestamp())
  order by 4,w.created_at;
end $function$;

create or replace function public.srk_guard_worker_session()
returns trigger
language plpgsql
set search_path to 'pg_catalog','public'
as $function$
declare v_worker_id uuid;
begin
  select bw.worker_id into v_worker_id
  from public.srk_booking_workers bw
  where bw.id=new.booking_worker_id;
  if v_worker_id is null then raise exception 'Booking worker assignment not found'; end if;

  perform pg_advisory_xact_lock(hashtextextended(v_worker_id::text,0));

  if new.session_status in ('running','paused') then
    if exists(
      select 1
      from public.srk_worker_work_sessions s
      where s.worker_id=v_worker_id
        and s.session_status in ('running','paused')
        and s.id<>coalesce(new.id,'00000000-0000-0000-0000-000000000000'::uuid)
    ) then
      raise exception 'Worker already has an active or paused work session at another booking';
    end if;
  end if;
  return new;
end $function$;

create or replace function public.srk_worker_respond_assignment(p_assignment_id uuid,p_accept boolean)
returns public.srk_booking_workers
language plpgsql
security definer
set search_path to 'pg_catalog','public','auth'
as $function$
declare
 v_assignment public.srk_booking_workers%rowtype;
 v_worker public.srk_worker_profiles%rowtype;
 v_booking public.service_bookings%rowtype;
 v_accepted_count integer;
 v_requested_count integer;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;

 select bw.* into v_assignment
 from public.srk_booking_workers bw
 join public.srk_worker_profiles wp on wp.id=bw.worker_id
 where bw.id=p_assignment_id and wp.user_id=auth.uid()
 for update of bw;

 if not found or v_assignment.assignment_status<>'offered' then
  raise exception 'Offer not found or no longer pending';
 end if;

 select * into v_booking from public.service_bookings
 where id=v_assignment.booking_id for update;
 if not found or v_booking.status='cancelled' then
  raise exception 'Booking is no longer available';
 end if;

 select * into v_worker from public.srk_worker_profiles
 where id=v_assignment.worker_id for update;
 if not found then raise exception 'Worker profile not found'; end if;

 if p_accept then
  if v_worker.verification_status<>'approved' or not v_worker.is_active then
   raise exception 'Worker is not currently approved and active';
  end if;

  -- Serialize acceptance with timer start/pause operations for this worker.
  perform pg_advisory_xact_lock(hashtextextended(v_worker.id::text,0));

  if exists(
    select 1 from public.srk_worker_work_sessions s
    where s.worker_id=v_worker.id and s.session_status in ('running','paused')
  ) or exists(
    select 1 from public.srk_booking_workers bw
    where bw.worker_id=v_worker.id and bw.assignment_status in ('working','paused')
  ) then
   raise exception 'Finish or complete the active/paused booking before accepting another booking';
  end if;

  v_requested_count:=case when v_assignment.worker_role='technician'
   then v_booking.requested_technician_count else v_booking.requested_helper_count end;

  select count(*) into v_accepted_count
  from public.srk_booking_workers
  where booking_id=v_assignment.booking_id
   and worker_role=v_assignment.worker_role
   and assignment_status in ('accepted','assigned','working','paused','completed');

  if v_accepted_count>=v_requested_count then
   raise exception 'Requested number of this worker role has already been filled';
  end if;
 end if;

 update public.srk_booking_workers
 set assignment_status=case when p_accept then 'accepted' else 'rejected' end,
  accepted_at=case when p_accept then clock_timestamp() else null end,
  rejected_at=case when p_accept then null else clock_timestamp() end,
  offer_expires_at=null,updated_at=clock_timestamp()
 where id=p_assignment_id returning * into v_assignment;

 if p_accept and v_assignment.worker_role='technician' then
  update public.service_bookings set status='confirmed'
  where id=v_assignment.booking_id and status='new';
 end if;

 update public.srk_booking_matching_queue
 set queue_status='pending',next_attempt_at=clock_timestamp(),updated_at=clock_timestamp()
 where booking_id=v_assignment.booking_id and queue_status not in ('fulfilled','cancelled');

 return v_assignment;
end
$function$;

